{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "account_setup_card",
        "fund_transfers_card",
        "security_features_card",
        "quick_actions_stack",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Mobile Banking App FAQs",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Here are some frequently asked questions to help users navigate your new mobile banking application, covering essential topics from initial setup to security."
      },
      "children": []
    },
    "account_setup_card": {
      "type": "Card",
      "props": {},
      "children": [
        "account_setup_title",
        "q1_stack",
        "q2_stack",
        "q3_stack",
        "q4_stack"
      ]
    },
    "account_setup_title": {
      "type": "Text",
      "props": {
        "text": "Account Setup & Access",
        "variant": "h2"
      },
      "children": []
    },
    "q1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q1_text",
        "q1_answers"
      ]
    },
    "q1_text": {
      "type": "Text",
      "props": {
        "text": "How do I register for the mobile banking app?"
      },
      "children": []
    },
    "q1_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q1_ans1",
        "q1_ans2"
      ]
    },
    "q1_ans1": {
      "type": "Text",
      "props": {
        "text": "Download the app from your device's app store."
      },
      "children": []
    },
    "q1_ans2": {
      "type": "Text",
      "props": {
        "text": "Select \"Register\" or \"Sign Up\" and follow the on-screen prompts to verify your identity and create your login credentials."
      },
      "children": []
    },
    "q2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q2_text",
        "q2_answers"
      ]
    },
    "q2_text": {
      "type": "Text",
      "props": {
        "text": "What information do I need to register?"
      },
      "children": []
    },
    "q2_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q2_ans1"
      ]
    },
    "q2_ans1": {
      "type": "Text",
      "props": {
        "text": "You will typically need your bank account number, registered mobile number, and possibly your debit card details or national ID for verification."
      },
      "children": []
    },
    "q3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q3_text",
        "q3_answers"
      ]
    },
    "q3_text": {
      "type": "Text",
      "props": {
        "text": "Can I link multiple bank accounts to the app?"
      },
      "children": []
    },
    "q3_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q3_ans1"
      ]
    },
    "q3_ans1": {
      "type": "Text",
      "props": {
        "text": "Yes, you can link all eligible accounts associated with your customer ID after initial setup. Navigate to the \"Accounts\" section to add more."
      },
      "children": []
    },
    "q4_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q4_text",
        "q4_answers"
      ]
    },
    "q4_text": {
      "type": "Text",
      "props": {
        "text": "What should I do if I forget my login PIN or password?"
      },
      "children": []
    },
    "q4_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q4_ans1"
      ]
    },
    "q4_ans1": {
      "type": "Text",
      "props": {
        "text": "On the login screen, tap \"Forgot PIN/Password\" and follow the secure steps to reset your credentials using registered details."
      },
      "children": []
    },
    "fund_transfers_card": {
      "type": "Card",
      "props": {},
      "children": [
        "fund_transfers_title",
        "q5_stack",
        "q6_stack",
        "q7_stack",
        "q8_stack",
        "q9_stack"
      ]
    },
    "fund_transfers_title": {
      "type": "Text",
      "props": {
        "text": "Fund Transfers & Payments",
        "variant": "h2"
      },
      "children": []
    },
    "q5_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q5_text",
        "q5_answers"
      ]
    },
    "q5_text": {
      "type": "Text",
      "props": {
        "text": "How do I send money using the app?"
      },
      "children": []
    },
    "q5_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q5_ans1"
      ]
    },
    "q5_ans1": {
      "type": "Text",
      "props": {
        "text": "Select \"Transfer Funds,\" choose the recipient (from saved beneficiaries or new), enter the amount, and confirm the transaction with your PIN or biometric authentication."
      },
      "children": []
    },
    "q6_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q6_text",
        "q6_answers"
      ]
    },
    "q6_text": {
      "type": "Text",
      "props": {
        "text": "What are the daily transfer limits?"
      },
      "children": []
    },
    "q6_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q6_ans1"
      ]
    },
    "q6_ans1": {
      "type": "Text",
      "props": {
        "text": "Transfer limits vary by account type and security settings. You can view your specific limits in the \"Settings\" or \"Limits\" section of the app."
      },
      "children": []
    },
    "q7_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q7_text",
        "q7_answers"
      ]
    },
    "q7_text": {
      "type": "Text",
      "props": {
        "text": "How long does it take for a fund transfer to complete?"
      },
      "children": []
    },
    "q7_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q7_ans1"
      ]
    },
    "q7_ans1": {
      "type": "Text",
      "props": {
        "text": "Internal transfers are usually instant. External transfers typically take 1-3 business days, depending on the recipient bank and transfer type."
      },
      "children": []
    },
    "q8_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q8_text",
        "q8_answers"
      ]
    },
    "q8_text": {
      "type": "Text",
      "props": {
        "text": "Can I schedule recurring payments?"
      },
      "children": []
    },
    "q8_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q8_ans1"
      ]
    },
    "q8_ans1": {
      "type": "Text",
      "props": {
        "text": "Yes, navigate to \"Scheduled Payments\" or \"Bill Pay\" to set up recurring transfers or bill payments."
      },
      "children": []
    },
    "q9_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q9_text",
        "q9_answers"
      ]
    },
    "q9_text": {
      "type": "Text",
      "props": {
        "text": "What if a payment fails or is incorrect?"
      },
      "children": []
    },
    "q9_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q9_ans1"
      ]
    },
    "q9_ans1": {
      "type": "Text",
      "props": {
        "text": "Check your transaction history for details. If the issue persists, contact customer support immediately with the transaction reference number."
      },
      "children": []
    },
    "security_features_card": {
      "type": "Card",
      "props": {},
      "children": [
        "security_features_title",
        "q10_stack",
        "q11_stack",
        "q12_stack"
      ]
    },
    "security_features_title": {
      "type": "Text",
      "props": {
        "text": "Security Features",
        "variant": "h2"
      },
      "children": []
    },
    "q10_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q10_text",
        "q10_answers"
      ]
    },
    "q10_text": {
      "type": "Text",
      "props": {
        "text": "How secure is the mobile banking app?"
      },
      "children": []
    },
    "q10_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q10_ans1"
      ]
    },
    "q10_ans1": {
      "type": "Text",
      "props": {
        "text": "The app uses advanced encryption, multi-factor authentication (MFA), and biometric login options (fingerprint/face ID) to protect your data and transactions."
      },
      "children": []
    },
    "q11_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q11_text",
        "q11_answers"
      ]
    },
    "q11_text": {
      "type": "Text",
      "props": {
        "text": "What is multi-factor authentication (MFA)?"
      },
      "children": []
    },
    "q11_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q11_ans1"
      ]
    },
    "q11_ans1": {
      "type": "Text",
      "props": {
        "text": "MFA adds an extra layer of security by requiring two or more verification methods, such as your password and a one-time code sent to your registered mobile number."
      },
      "children": []
    },
    "q12_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "q12_text",
        "q12_answers"
      ]
    },
    "q12_text": {
      "type": "Text",
      "props": {
        "text": "How can I protect my account from fraud?"
      },
      "children": []
    },
    "q12_answers": {
      "type": "List",
      "props": {},
      "children": [
        "q12_ans1"
      ]
    },
    "q12_ans1": {
      "type": "Text",
      "props": {
        "text": "Always use strong, unique passwords, enable biometric login, never share your PIN/password, and regularly review your transaction history. Report suspicious activity immediately."
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_title",
        "contact_support_button",
        "find_atm_button"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "contact_support_button": {
      "type": "Button",
      "props": {
        "label": "Contact Support"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/support"
          }
        }
      }
    },
    "find_atm_button": {
      "type": "Button",
      "props": {
        "label": "Find ATM/Branch"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/locations"
          }
        }
      }
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title",
        "source_text"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "source_text": {
      "type": "Text",
      "props": {
        "text": "For more details, visit our official website: https://www.example.com/mobile-banking-faq"
      },
      "children": []
    }
  }
}
